      final sdk = makeSdkRoot();
      for (final v in ['3.47.4', '3.48.0']) {
        Directory('${sdk.path}/$v/bin').createSync(recursive: true);
        File('${sdk.path}/$v/bin/flutter').writeAsStringSync(v);
