      final sdk = makeSdkRoot();
      final result = resolve(
        '3.99.x',
        sdk.path,
        marker: '3.47.4',
        manifest: writeManifest(sdk.parent),
      );
      expect(result.exitCode, isNot(0));
      expect(result.stderr, contains('no stable release matches'));
    });
  });

