        '${sdk.path}/3.47.4',
      ]);
      expect(result.exitCode, 0, reason: result.stderr);
      expect(File('${sdk.path}/3.47.4/bin/flutter').existsSync(), isTrue);
      expect(Directory('${sdk.path}/.stage.abc/flutter').existsSync(), isFalse);
